//! Emits the Java codec (`protocol/java/src/main/java/io/kronosdb/protocol`)
//! and its JSON bridge for the conformance suite (`src/test/java/...`).
//!
//! Java 21, no dependencies. Structs and frames are records, unions are
//! sealed interfaces with one record per variant, and enums are small value
//! records so a value this version does not know survives a decode and an
//! encode, like in the Rust and TypeScript codecs. Hand-written runtime code
//! (`java_runtime/*.java`: reader, writer, exception, JSON) is embedded and
//! emitted next to the generated files so nothing under `protocol/java/src`
//! is maintained by hand except the test class itself.

use std::fmt::Write;

use crate::schema::{EVENT_RECORD, Enum, Schema, Struct, Type, Union, Width};

pub const PACKAGE: &str = "io.kronosdb.protocol";

const READER: &str = include_str!("java_runtime/Reader.java");
const WRITER: &str = include_str!("java_runtime/Writer.java");
const EXCEPTION: &str = include_str!("java_runtime/ProtocolException.java");
const JSON: &str = include_str!("java_runtime/Json.java");

/// Where a generated file goes, relative to `protocol/java`.
pub struct JavaFile {
    pub path: String,
    pub content: String,
}

const JAVA_KEYWORDS: &[&str] = &[
    "abstract",
    "assert",
    "boolean",
    "break",
    "byte",
    "case",
    "catch",
    "char",
    "class",
    "const",
    "continue",
    "default",
    "do",
    "double",
    "else",
    "enum",
    "extends",
    "final",
    "finally",
    "float",
    "for",
    "goto",
    "if",
    "implements",
    "import",
    "instanceof",
    "int",
    "interface",
    "long",
    "native",
    "new",
    "package",
    "private",
    "protected",
    "public",
    "return",
    "short",
    "static",
    "strictfp",
    "super",
    "switch",
    "synchronized",
    "this",
    "throw",
    "throws",
    "transient",
    "try",
    "void",
    "volatile",
    "while",
];

/// Schema names are snake_case; Java components are camelCase.
fn camel(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut upper = false;
    for c in name.chars() {
        if c == '_' {
            upper = true;
        } else if upper {
            out.push(c.to_ascii_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    if JAVA_KEYWORDS.contains(&out.as_str()) {
        out.push('_');
    }
    out
}

fn pascal(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut upper = true;
    for c in name.chars() {
        if c == '_' {
            upper = true;
        } else if upper {
            out.push(c.to_ascii_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

fn header() -> String {
    "// @generated by protocol-gen from protocol/kronosdb.schema. Do not edit;\n\
     // change the schema and run `just protocol`.\n"
        .to_string()
}

/// Schema docs are Markdown-ish: `code` spans become `{@code}`, everything
/// else is HTML-escaped so Javadoc accepts it.
fn doc_line(line: &str) -> String {
    let mut out = String::new();
    let mut in_code = false;
    for c in line.chars() {
        match c {
            '`' => {
                out.push_str(if in_code { "}" } else { "{@code " });
                in_code = !in_code;
            }
            '&' if !in_code => out.push_str("&amp;"),
            '<' if !in_code => out.push_str("&lt;"),
            '>' if !in_code => out.push_str("&gt;"),
            '@' if !in_code => out.push_str("&#64;"),
            _ => out.push(c),
        }
    }
    if in_code {
        out.push('}');
    }
    out.replace("*/", "*&#47;")
}

fn javadoc(o: &mut String, indent: &str, lines: &[String]) {
    if lines.is_empty() {
        return;
    }
    writeln!(o, "{indent}/**").unwrap();
    for line in lines {
        if line.is_empty() {
            writeln!(o, "{indent} * <p>").unwrap();
        } else {
            writeln!(o, "{indent} * {}", doc_line(line)).unwrap();
        }
    }
    writeln!(o, "{indent} */").unwrap();
}

/// Javadoc for a record: its doc, then one `@param` per component.
fn record_doc(o: &mut String, indent: &str, doc: &[String], s: &Struct) {
    let mut lines: Vec<String> = doc.to_vec();
    if !s.fields.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        for f in &s.fields {
            let mut text = f.doc.join(" ");
            if text.is_empty() {
                text = format!("the {}", f.name.replace('_', " "));
            }
            if matches!(f.ty, Type::Opt(_)) {
                if !text.is_empty() {
                    text.push(' ');
                }
                text.push_str("May be null: absent on the wire.");
            }
            lines.push(
                format!("@param {} {}", camel(&f.name), text)
                    .trim_end()
                    .to_string(),
            );
        }
    }
    // `@param` lines are Javadoc tags: they must not pass through doc_line's
    // `@` escaping.
    if lines.is_empty() {
        return;
    }
    writeln!(o, "{indent}/**").unwrap();
    for (i, line) in lines.iter().enumerate() {
        if line.is_empty() {
            // The gap before the @param block is not a paragraph.
            let before_params = lines.get(i + 1).is_some_and(|n| n.starts_with("@param "));
            writeln!(o, "{indent} *{}", if before_params { "" } else { " <p>" }).unwrap();
        } else if let Some(rest) = line.strip_prefix("@param ") {
            let (name, text) = rest.split_once(' ').unwrap_or((rest, ""));
            writeln!(o, "{indent} * @param {name} {}", doc_line(text)).unwrap();
        } else {
            writeln!(o, "{indent} * {}", doc_line(line)).unwrap();
        }
    }
    writeln!(o, "{indent} */").unwrap();
}

fn jtype(ty: &Type, boxed: bool) -> String {
    let prim = |p: &str, b: &str| if boxed { b.to_string() } else { p.to_string() };
    match ty {
        Type::U8 | Type::U16 => prim("int", "Integer"),
        Type::U32 | Type::U64 | Type::I64 | Type::Millis => prim("long", "Long"),
        Type::Bool => prim("boolean", "Boolean"),
        Type::F64 => prim("double", "Double"),
        Type::Str(_) => "String".into(),
        Type::Bytes(_) => "ByteBuffer".into(),
        Type::List(_, inner) => format!("List<{}>", jtype(inner, true)),
        Type::Opt(inner) => jtype(inner, true),
        Type::Record => "StoredRecord".into(),
        Type::Records => "List<StoredRecord>".into(),
        Type::Named(name) => name.clone(),
    }
}

fn width(w: Width) -> &'static str {
    match w {
        Width::W16 => "16",
        Width::W32 => "32",
    }
}

fn decode_expr(schema: &Schema, ty: &Type, r: &str, depth: usize) -> String {
    match ty {
        Type::U8 => format!("{r}.readU8()"),
        Type::U16 => format!("{r}.readU16()"),
        Type::U32 => format!("{r}.readU32()"),
        Type::U64 => format!("{r}.readU64()"),
        Type::I64 => format!("{r}.readI64()"),
        Type::Millis => format!("{r}.readMillis()"),
        Type::Bool => format!("{r}.readBool()"),
        Type::F64 => format!("{r}.readF64()"),
        Type::Str(w) => format!("{r}.readStr{}()", width(*w)),
        Type::Bytes(w) => format!("{r}.readBytes{}()", width(*w)),
        Type::List(w, inner) => {
            let next = format!("r{}", depth + 1);
            format!(
                "{r}.readList{}({next} -> {})",
                width(*w),
                decode_expr(schema, inner, &next, depth + 1)
            )
        }
        Type::Opt(inner) => format!(
            "({r}.readPresent() ? {} : null)",
            decode_expr(schema, inner, r, depth)
        ),
        Type::Record => format!("StoredRecord.decode({r})"),
        Type::Records => format!("StoredRecord.decodeAll({r})"),
        Type::Named(name) => match schema.enum_named(name) {
            Some(e) if e.repr == Type::U8 => format!("{name}.of({r}.readU8())"),
            Some(_) => format!("{name}.of({r}.readU16())"),
            None => format!("{name}.decode({r})"),
        },
    }
}

fn encode_stmt(schema: &Schema, ty: &Type, x: &str, ctx: &str, depth: usize) -> String {
    match ty {
        Type::U8 => format!("w.writeU8({x});"),
        Type::U16 => format!("w.writeU16({x});"),
        Type::U32 => format!("w.writeU32({x});"),
        Type::U64 => format!("w.writeU64({x});"),
        Type::I64 => format!("w.writeI64({x});"),
        Type::Millis => format!("w.writeMillis({x});"),
        Type::Bool => format!("w.writeBool({x});"),
        Type::F64 => format!("w.writeF64({x});"),
        Type::Str(wd) => format!("w.writeStr{}({x}, \"{ctx}\");", width(*wd)),
        Type::Bytes(wd) => format!("w.writeBytes{}({x}, \"{ctx}\");", width(*wd)),
        Type::List(wd, inner) => {
            let item = format!("e{depth}");
            format!(
                "w.writeLen{}({x}.size(), \"{ctx}\");\n        for ({} {item} : {x}) {{\n            {}\n        }}",
                width(*wd),
                jtype(inner, true),
                encode_stmt(schema, inner, &item, ctx, depth + 1)
            )
        }
        Type::Opt(inner) => format!(
            "if ({x} == null) {{\n            w.writeU8(0);\n        }} else {{\n            w.writeU8(1);\n            {}\n        }}",
            encode_stmt(schema, inner, x, ctx, depth + 1)
        ),
        Type::Record => format!("{x}.encode(w);"),
        Type::Records => format!("StoredRecord.encodeAll(w, {x}, \"{ctx}\");"),
        Type::Named(name) => match schema.enum_named(name) {
            Some(e) if e.repr == Type::U8 => format!("w.writeU8({x}.value());"),
            Some(_) => format!("w.writeU16({x}.value());"),
            None => format!("{x}.encode(w);"),
        },
    }
}

const IMPORTS: &str = "import java.nio.ByteBuffer;\nimport java.util.List;\n";

fn file_start(o: &mut String, imports: &str) {
    o.push_str(&header());
    writeln!(o, "package {PACKAGE};").unwrap();
    writeln!(o).unwrap();
    if !imports.is_empty() {
        o.push_str(imports);
        writeln!(o).unwrap();
    }
}

pub fn emit_codec(schema: &Schema, schema_hash: &str) -> Vec<JavaFile> {
    let main = "src/main/java/io/kronosdb/protocol";
    let mut files = Vec::new();
    let mut add = |name: &str, content: String| {
        files.push(JavaFile {
            path: format!("{main}/{name}.java"),
            content,
        });
    };

    add("package-info", package_info());
    for (name, src) in [
        ("ProtocolException", EXCEPTION),
        ("Reader", READER),
        ("Writer", WRITER),
    ] {
        add(name, format!("{}{src}", header()));
    }
    for e in &schema.enums {
        add(&e.name, emit_enum(e));
    }
    for u in &schema.unions {
        add(&u.name, emit_union(schema, u));
    }
    for s in &schema.structs {
        add(&s.name, emit_struct(schema, s));
    }
    add("StoredRecord", emit_stored_record());
    add("Frame", emit_frame_interface(schema));
    add("FrameHeader", emit_frame_header());
    add("Frames", emit_frames(schema, schema_hash));
    files
}

fn package_info() -> String {
    let mut o = header();
    o.push_str(
        r#"
/**
 * The KronosDB native protocol: a zero-dependency codec for every frame in
 * {@code protocol/kronosdb.schema}.
 *
 * <p>Java types of schema types:
 *
 * <ul>
 *   <li>{@code u8}, {@code u16}: {@code int}
 *   <li>{@code u32}: {@code long}, always non-negative
 *   <li>{@code u64}: {@code long} with <em>unsigned</em> meaning; compare with
 *       {@link Long#compareUnsigned} and print with {@link Long#toUnsignedString}
 *   <li>{@code i64}, {@code millis}: {@code long}
 *   <li>{@code bool}: {@code boolean}; {@code f64}: {@code double}
 *   <li>{@code str16}, {@code str32}: {@code String}
 *   <li>{@code bytes16}, {@code bytes32}: {@link java.nio.ByteBuffer}, a slice of the array
 *       the frame was decoded from (not a copy); treat it as read-only
 *   <li>{@code list16<T>}, {@code list32<T>}: {@code List<T>}, to be treated as read-only
 *   <li>{@code opt<T>}: the boxed type, {@code null} when absent
 *   <li>enums: a small value record with constants; unknown values are kept
 *   <li>unions: a sealed interface with one record per variant
 * </ul>
 */
package io.kronosdb.protocol;
"#,
    );
    o
}

fn emit_enum(e: &Enum) -> String {
    let mut o = String::new();
    file_start(&mut o, "");
    let mut doc = e.doc.clone();
    doc.push(String::new());
    doc.push("Open: a value this version does not know is kept as it arrived.".into());
    javadoc(&mut o, "", &doc);
    writeln!(o, "public record {0}(int value) {{", e.name).unwrap();
    for v in &e.variants {
        writeln!(o).unwrap();
        javadoc(&mut o, "    ", &v.doc);
        writeln!(
            o,
            "    public static final {0} {1} = new {0}({2});",
            e.name,
            v.name.to_ascii_uppercase(),
            v.value
        )
        .unwrap();
    }
    writeln!(o).unwrap();
    writeln!(
        o,
        "    /** The value {{@code value}}: a constant if this version knows it. */"
    )
    .unwrap();
    writeln!(o, "    public static {} of(int value) {{", e.name).unwrap();
    writeln!(o, "        return switch (value) {{").unwrap();
    for v in &e.variants {
        writeln!(
            o,
            "            case {} -> {};",
            v.value,
            v.name.to_ascii_uppercase()
        )
        .unwrap();
    }
    writeln!(o, "            default -> new {}(value);", e.name).unwrap();
    writeln!(o, "        }};").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    /** The schema's name for this value, or {{@code null}} if this version does not know it. */"
    )
    .unwrap();
    writeln!(o, "    public String variantName() {{").unwrap();
    writeln!(o, "        return switch (value) {{").unwrap();
    for v in &e.variants {
        writeln!(o, "            case {} -> \"{}\";", v.value, v.name).unwrap();
    }
    writeln!(o, "            default -> null;").unwrap();
    writeln!(o, "        }};").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    /** The value the schema calls {{@code name}}, or -1 if there is none. */"
    )
    .unwrap();
    writeln!(o, "    public static int valueOfName(String name) {{").unwrap();
    writeln!(o, "        return switch (name) {{").unwrap();
    for v in &e.variants {
        writeln!(o, "            case \"{}\" -> {};", v.name, v.value).unwrap();
    }
    writeln!(o, "            default -> -1;").unwrap();
    writeln!(o, "        }};").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    @Override").unwrap();
    writeln!(o, "    public String toString() {{").unwrap();
    writeln!(o, "        String name = variantName();").unwrap();
    writeln!(
        o,
        "        return name != null ? name : \"{}(\" + value + \")\";",
        e.name
    )
    .unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
    o
}

fn variant_class(v: &crate::schema::UnionVariant) -> String {
    format!("Of{}", pascal(&v.name))
}

fn emit_union(schema: &Schema, u: &Union) -> String {
    let mut o = String::new();
    file_start(&mut o, IMPORTS);
    javadoc(&mut o, "", &u.doc);
    writeln!(o, "public sealed interface {} {{", u.name).unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    void encode(Writer w);").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    static {} decode(Reader r) {{", u.name).unwrap();
    writeln!(o, "        int tag = r.readU8();").unwrap();
    writeln!(o, "        return switch (tag) {{").unwrap();
    for v in &u.variants {
        writeln!(
            o,
            "            case {} -> new {}({});",
            v.tag,
            variant_class(v),
            decode_expr(schema, &v.ty, "r", 0)
        )
        .unwrap();
    }
    writeln!(
        o,
        "            default -> throw new ProtocolException(\"{} has no variant with tag \" + tag);",
        u.name
    )
    .unwrap();
    writeln!(o, "        }};").unwrap();
    writeln!(o, "    }}").unwrap();
    for v in &u.variants {
        writeln!(o).unwrap();
        javadoc(&mut o, "    ", &v.doc);
        writeln!(
            o,
            "    record {}({} value) implements {} {{",
            variant_class(v),
            jtype(&v.ty, false),
            u.name
        )
        .unwrap();
        writeln!(o, "        @Override").unwrap();
        writeln!(o, "        public void encode(Writer w) {{").unwrap();
        writeln!(o, "            w.writeU8({});", v.tag).unwrap();
        writeln!(
            o,
            "            {}",
            encode_stmt(schema, &v.ty, "value", &format!("{}.{}", u.name, v.name), 0)
                .replace("\n        ", "\n            ")
        )
        .unwrap();
        writeln!(o, "        }}").unwrap();
        writeln!(o, "    }}").unwrap();
    }
    writeln!(o, "}}").unwrap();
    o
}

fn emit_struct(schema: &Schema, s: &Struct) -> String {
    let mut o = String::new();
    file_start(&mut o, IMPORTS);
    record_doc(&mut o, "", &s.doc, s);
    let components: Vec<String> = s
        .fields
        .iter()
        .map(|f| format!("{} {}", jtype(&f.ty, false), camel(&f.name)))
        .collect();
    let implements = if s.kind.is_some() {
        " implements Frame"
    } else {
        ""
    };
    writeln!(
        o,
        "public record {}({}){implements} {{",
        s.name,
        components.join(", ")
    )
    .unwrap();
    if let Some(kind) = s.kind {
        writeln!(o).unwrap();
        writeln!(o, "    /** The frame kind on the wire. */").unwrap();
        writeln!(o, "    public static final int KIND = {kind:#06x};").unwrap();
        writeln!(o).unwrap();
        writeln!(o, "    @Override").unwrap();
        writeln!(o, "    public int kind() {{").unwrap();
        writeln!(o, "        return KIND;").unwrap();
        writeln!(o, "    }}").unwrap();
    }
    writeln!(o).unwrap();
    writeln!(o, "    public static {} decode(Reader r) {{", s.name).unwrap();
    if s.fields.is_empty() {
        writeln!(o, "        return new {}();", s.name).unwrap();
    } else {
        // Java evaluates arguments left to right, which is declaration order.
        writeln!(o, "        return new {}(", s.name).unwrap();
        let args: Vec<String> = s
            .fields
            .iter()
            .map(|f| format!("                {}", decode_expr(schema, &f.ty, "r", 0)))
            .collect();
        writeln!(o, "{});", args.join(",\n")).unwrap();
    }
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    if s.kind.is_some() {
        writeln!(o, "    @Override").unwrap();
    }
    writeln!(o, "    public void encode(Writer w) {{").unwrap();
    for f in &s.fields {
        let ctx = format!("{}.{}", s.name, f.name);
        writeln!(
            o,
            "        {}",
            encode_stmt(schema, &f.ty, &camel(&f.name), &ctx, 0)
        )
        .unwrap();
    }
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
    o
}

fn emit_stored_record() -> String {
    let mut o = String::new();
    file_start(
        &mut o,
        "import java.util.ArrayList;\nimport java.util.List;\n",
    );
    write!(
        o,
        r#"/**
 * One event record: {{@code len u32 | flags u8 | body}}, the stored layout
 * without its leading CRC. {{@code flags}} is 0 for an event; the body is an
 * {{@link {e}}}.
 *
 * @param flags the record flags
 * @param event the event
 */
public record StoredRecord(int flags, {e} event) {{

    public static StoredRecord decode(Reader r) {{
        long len = r.readU32();
        if (len == 0) {{
            throw new ProtocolException("zero-length record");
        }}
        int flags = r.readU8();
        long bodyEnd = (long) r.position() + len - 1;
        if (bodyEnd > r.end()) {{
            throw new ProtocolException("record extends past the frame");
        }}
        int outer = r.limit((int) bodyEnd);
        {e} event = {e}.decode(r);
        if (r.position() != bodyEnd) {{
            throw new ProtocolException("record body has trailing bytes");
        }}
        r.restore(outer);
        return new StoredRecord(flags, event);
    }}

    public static List<StoredRecord> decodeAll(Reader r) {{
        long n = r.readU32();
        if (n == 0) {{
            return List.of();
        }}
        if (n > Integer.MAX_VALUE) {{
            throw new ProtocolException("list of " + n + " records");
        }}
        List<StoredRecord> out = new ArrayList<>((int) Math.min(n, 256));
        for (long i = 0; i < n; i++) {{
            out.add(decode(r));
        }}
        return out;
    }}

    public void encode(Writer w) {{
        int lenAt = w.position();
        w.writeU32(0);
        w.writeU8(flags);
        int start = w.position();
        event.encode(w);
        w.patchU32(lenAt, 1L + (w.position() - start));
    }}

    public static void encodeAll(Writer w, List<StoredRecord> records, String ctx) {{
        w.writeLen32(records.size(), ctx);
        for (StoredRecord record : records) {{
            record.encode(w);
        }}
    }}
}}
"#,
        e = EVENT_RECORD
    )
    .unwrap();
    o
}

fn emit_frame_interface(schema: &Schema) -> String {
    let mut o = String::new();
    file_start(&mut o, "");
    writeln!(
        o,
        "/** Every frame this version knows. Kinds with the 0x8000 bit are sent by the server. */"
    )
    .unwrap();
    let names: Vec<&str> = schema.frames().map(|f| f.name.as_str()).collect();
    writeln!(o, "public sealed interface Frame permits").unwrap();
    for (i, n) in names.iter().enumerate() {
        let sep = if i + 1 == names.len() { " {" } else { "," };
        writeln!(o, "        {n}{sep}").unwrap();
    }
    writeln!(o).unwrap();
    writeln!(o, "    /** The frame kind on the wire. */").unwrap();
    writeln!(o, "    int kind();").unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    /** Writes the body: the fields, without the frame header. */"
    )
    .unwrap();
    writeln!(o, "    void encode(Writer w);").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    default boolean sentByServer() {{").unwrap();
    writeln!(o, "        return (kind() & 0x8000) != 0;").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
    o
}

fn emit_frame_header() -> String {
    let mut o = String::new();
    file_start(&mut o, "");
    o.push_str(
        r#"/**
 * A frame's header, as {@link Frames#readHeader} finds it in a buffer.
 *
 * @param kind the frame kind
 * @param flags the flag bits; see {@link Frames#FLAG_END}
 * @param stream the stream id, an unsigned 32-bit number held in an {@code int}
 * @param bodyStart the offset of the body in the buffer
 * @param end the offset just past the frame
 */
public record FrameHeader(int kind, int flags, int stream, int bodyStart, int end) {

    public boolean isEnd() {
        return (flags & Frames.FLAG_END) != 0;
    }
}
"#,
    );
    o
}

fn emit_frames(schema: &Schema, hash: &str) -> String {
    let mut o = String::new();
    file_start(&mut o, "import java.nio.charset.StandardCharsets;\n");
    writeln!(
        o,
        "/** Frame framing: the header, the preface, and decoding and encoding any frame by kind. */"
    )
    .unwrap();
    writeln!(o, "public final class Frames {{").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    private Frames() {{").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    /** The protocol version this code speaks. */").unwrap();
    writeln!(
        o,
        "    public static final int PROTOCOL_VERSION = {};",
        schema.version
    )
    .unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    /** CRC32C of the schema source, for checking generated code is in sync. */"
    )
    .unwrap();
    writeln!(
        o,
        "    public static final String SCHEMA_HASH = \"{hash}\";"
    )
    .unwrap();
    o.push_str(
        r#"
    /** Bytes every connection starts with, before the client's Hello. Do not modify. */
    public static final byte[] PREFACE = "KRONOSDB".getBytes(StandardCharsets.US_ASCII);

    /** {@code len u32 | kind u16 | flags u8 | stream u32}; {@code len} counts everything after itself. */
    public static final int HEADER_LEN = 11;

    /** Set on the last frame a sender will send on a stream. */
    public static final int FLAG_END = 0x01;

    /** The {@code len} field of the header at {@code offset}: the bytes after it. */
    public static long length(byte[] buf, int offset) {
        long len = Reader.u32At(buf, offset);
        if (len < HEADER_LEN - 4) {
            throw new ProtocolException("frame length " + len + " is shorter than its header");
        }
        return len;
    }

    public static int kind(byte[] buf, int offset) {
        return Reader.u16At(buf, offset + 4);
    }

    public static int flags(byte[] buf, int offset) {
        return buf[offset + 6] & 0xFF;
    }

    /** The stream id, an unsigned 32-bit number held in an {@code int}. */
    public static int stream(byte[] buf, int offset) {
        return (int) Reader.u32At(buf, offset + 7);
    }

    /**
     * The header of the frame at {@code offset} in {@code buf[0, limit)}, or
     * {@code null} if the whole frame has not arrived yet.
     */
    public static FrameHeader readHeader(byte[] buf, int offset, int limit) {
        if (limit - offset < HEADER_LEN) {
            return null;
        }
        long len = length(buf, offset);
        long end = offset + 4 + len;
        if (end > limit) {
            return null;
        }
        return new FrameHeader(kind(buf, offset), flags(buf, offset), stream(buf, offset),
                offset + HEADER_LEN, (int) end);
    }

    /**
     * Decodes a frame body. {@code null} for a kind this version does not
     * know. Bytes after the declared fields are ignored: later minor versions
     * may append fields to a frame.
     */
    public static Frame decode(int kind, Reader r) {
        return switch (kind) {
"#,
    );
    for f in schema.frames() {
        writeln!(
            o,
            "            case {:#06x} -> {}.decode(r);",
            f.kind.unwrap(),
            f.name
        )
        .unwrap();
    }
    o.push_str(
        r#"            default -> null;
        };
    }

    /**
     * Appends a whole frame, header and body, to {@code w}. If encoding
     * fails, {@code w} is left as it was.
     *
     * @return the number of bytes written
     */
    public static int encode(Writer w, int stream, int flags, Frame frame) {
        int start = w.position();
        try {
            w.writeU32(0);
            w.writeU16(frame.kind());
            w.writeU8(flags);
            w.writeU32(stream & 0xFFFFFFFFL);
            frame.encode(w);
            w.patchU32(start, w.position() - start - 4L);
        } catch (RuntimeException e) {
            w.truncate(start);
            throw e;
        }
        return w.position() - start;
    }
}
"#,
    );
    o
}

// ---------------------------------------------------------------------------
// JSON bridge (conformance tests only)

fn to_json_expr(schema: &Schema, ty: &Type, x: &str, depth: usize) -> String {
    match ty {
        Type::U8 | Type::U16 | Type::U32 | Type::Millis => format!("Long.valueOf({x})"),
        Type::I64 => format!("Long.toString({x})"),
        Type::U64 => format!("Long.toUnsignedString({x})"),
        Type::Bool => format!("Boolean.valueOf({x})"),
        Type::F64 => format!("Double.valueOf({x})"),
        Type::Str(_) => x.to_string(),
        Type::Bytes(_) => format!("Json.hex({x})"),
        Type::List(_, inner) => {
            let item = format!("e{}", depth + 1);
            format!(
                "Json.list({x}, {item} -> {})",
                to_json_expr(schema, inner, &item, depth + 1)
            )
        }
        Type::Opt(inner) => format!(
            "({x} == null ? null : {})",
            to_json_expr(schema, inner, x, depth)
        ),
        Type::Record => format!("recordToJson({x})"),
        Type::Records => format!("Json.list({x}, ProtocolJson::recordToJson)"),
        Type::Named(name) => match schema.enum_named(name) {
            Some(_) => format!("Json.enumName({x}.variantName(), {x}.value())"),
            None => format!("toJson({x})"),
        },
    }
}

fn from_json_expr(schema: &Schema, ty: &Type, x: &str, depth: usize) -> String {
    match ty {
        Type::U8 | Type::U16 => format!("Json.intValue({x})"),
        Type::U32 | Type::Millis => format!("Json.longValue({x})"),
        Type::I64 => format!("Json.i64({x})"),
        Type::U64 => format!("Json.u64({x})"),
        Type::Bool => format!("Json.bool({x})"),
        Type::F64 => format!("Json.f64({x})"),
        Type::Str(_) => format!("Json.str({x})"),
        Type::Bytes(_) => format!("Json.bytes({x})"),
        Type::List(_, inner) => {
            let item = format!("j{}", depth + 1);
            format!(
                "Json.map({x}, {item} -> {})",
                from_json_expr(schema, inner, &item, depth + 1)
            )
        }
        Type::Opt(inner) => format!(
            "({x} == null ? null : {})",
            from_json_expr(schema, inner, x, depth)
        ),
        Type::Record => format!("recordFromJson({x})"),
        Type::Records => format!("Json.map({x}, ProtocolJson::recordFromJson)"),
        Type::Named(name) => match schema.enum_named(name) {
            Some(_) => format!("{name}.of(Json.enumValue({x}, {name}::valueOfName))"),
            None => format!("{}FromJson({x})", lower_first(name)),
        },
    }
}

fn lower_first(name: &str) -> String {
    let mut chars = name.chars();
    match chars.next() {
        Some(c) => c.to_ascii_lowercase().to_string() + chars.as_str(),
        None => String::new(),
    }
}

